#[test]
fn test_sort_natural() {
    let te = TestEnv::new(
        &[],
        &["file9.txt", "file10.txt", "file20.txt", "file2.txt", "file007.txt", "file7.txt"],
    );

    te.assert_output_order(
        &[".", "--sort", "name", "--sort-natural"],
        "file2.txt
        file7.txt
        file007.txt
        file9.txt
        file10.txt
        file20.txt",
    );
}

#[test]
fn test_sort_natural_case_sensitive() {
    let te = TestEnv::new(&[], &["File2.txt", "file10.txt", "file2.txt"]);

    te.assert_output_order(
        &[".", "--sort", "name", "--sort-natural", "--sort-case-sensitive"],
        "File2.txt
        file2.txt
        file10.txt",
    );
}

