#[test]
fn test_sort_max_results_after_sort() {
    let te = TestEnv::new(&[], &["c.txt", "a.txt", "b.txt", "d.txt", "e.txt"]);

    te.assert_output_order(
        &[".", "--sort", "name", "--max-results", "3"],
        "a.txt
        b.txt
        c.txt",
    );

    te.assert_output_order(
        &[".", "--sort", "name", "--reverse", "--max-results", "3"],
        "e.txt
        d.txt
        c.txt",
    );
}

#[test]
fn test_sort_random_seed_deterministic() {
    let te = TestEnv::new(&[], &["a.txt", "b.txt", "c.txt", "d.txt"]);

    let first = te.assert_success_and_get_ordered_output(".", &["--sort", "random", "--sort-seed", "42", "."]);
    let second = te.assert_success_and_get_ordered_output(".", &["--sort", "random", "--sort-seed", "42", "."]);
    assert_eq!(first, second);
}

#[test]
fn test_sort_random_differs_between_runs() {
    let te = TestEnv::new(&[], &["a.txt", "b.txt", "c.txt", "d.txt", "e.txt"]);

    let first = te.assert_success_and_get_ordered_output(".", &["--sort", "random", "."]);
    let second = te.assert_success_and_get_ordered_output(".", &["--sort", "random", "."]);
    // It is extremely unlikely that two independent time-derived seeds produce
    // the same order for five distinct paths.
    assert_ne!(first, second);
}

#[test]
fn test_sort_requires_sort() {
    let te = TestEnv::new(&[], &["a.txt"]);
    te.assert_failure_with_error(&["--reverse", "."], "required arguments were not provided");
}

#[test]
fn test_sort_seed_requires_sort() {
    let te = TestEnv::new(&[], &["a.txt"]);
    te.assert_failure_with_error(&["--sort-seed", "1", "."], "required arguments were not provided");
}

#[test]
fn test_sort_dirs_and_files_conflict() {
    let te = TestEnv::new(&[], &["a.txt"]);
    te.assert_failure(&["--sort", "name", "--dirs-first", "--files-first", "."]);
}

#[test]
fn test_sort_conflicts_with_exec() {
    let te = TestEnv::new(&[], &["a.txt"]);
    te.assert_failure(&["--sort", "name", "-x", "echo", "."]);
}

#[test]
fn test_sort_size_regular_files_only() {
    let te = TestEnv::new(&["dir"], &["big.txt", "small.txt"]);
    fs::write(te.test_root().join("big.txt"), "1234567890").unwrap();

    te.assert_output_order(
        &[".", "--sort", "size", "--sort", "path"],
        "dir/
        symlink
        small.txt
        big.txt",
    );
}
